"""Locate the wrapper behind a finding, and its callers, in a shallow clone of the library.

First choice is Entire's code graph. `entire agent-help` (CLI 0.11.4) lists no graph
command; `entire graph` answers that the entire-graph plugin is not installed, and
`agent-help` marks `entire plugin` as the user's to run, so Trueup does not install
it. Each run probes again and records what the CLI said. When the graph is not
there, the fallback is ripgrep for the seed symbols plus Python's ast for the
enclosing definitions, and locate.json says the graph was not used and why.
"""

from __future__ import annotations

import ast
import json
import shutil
import subprocess
from pathlib import Path
from typing import Any, Callable

from trueup.fixer.targets import REPOS, Target

Runner = Callable[[list[str], Path | None, float], subprocess.CompletedProcess]


def run_cmd(cmd: list[str], cwd: Path | None = None, timeout: float = 600) -> subprocess.CompletedProcess:
    return subprocess.run(cmd, cwd=cwd, capture_output=True, text=True, timeout=timeout)


def clone_dir(root: Path, library: str) -> Path:
    return root.resolve() / ".trueup" / "clones" / library


def ensure_clone(root: Path, library: str, run: Runner = run_cmd) -> tuple[Path, str]:
    """Shallow clone of the library's default branch. Returns (path, commit)."""
    d = clone_dir(root, library)
    if not (d / ".git").exists():
        d.parent.mkdir(parents=True, exist_ok=True)
        p = run(["git", "clone", "--quiet", "--depth", "1", REPOS[library], str(d)], None, 1200)
        if p.returncode != 0:
            raise RuntimeError(f"git clone {REPOS[library]} failed: {p.stderr.strip()[-300:]}")
    p = run(["git", "-C", str(d), "rev-parse", "HEAD"], None, 60)
    return d, p.stdout.strip()


def reset_clone(clone: Path, run: Runner = run_cmd) -> None:
    """Drop every local change in the clone (only the clone)."""
    run(["git", "-C", str(clone), "checkout", "--quiet", "--", "."], None, 120)
    run(["git", "-C", str(clone), "clean", "--quiet", "-fd"], None, 120)


def probe_graph(clone: Path, seeds: tuple[str, ...], run: Runner = run_cmd) -> dict[str, Any]:
    """Ask the installed Entire CLI for its code graph. Records every command and its output."""
    record: dict[str, Any] = {"used": False, "commands": []}
    if shutil.which("entire") is None:
        record["reason"] = "entire CLI not on PATH"
        return record
    for cmd in (["entire", "agent-help"], ["entire", "agent-help", "labs"], ["entire", "graph", "--help"]):
        try:
            p = run(cmd, clone, 60)
            text = (p.stdout + p.stderr).strip()
            record["commands"].append({"cmd": " ".join(cmd), "exit": p.returncode, "output": text[-3000:]})
        except (OSError, subprocess.TimeoutExpired) as e:
            record["commands"].append({"cmd": " ".join(cmd), "error": type(e).__name__})
    graph = record["commands"][-1]
    out = graph.get("output", "")
    if graph.get("exit") == 0 and "not installed" not in out:
        # The graph answered. Its subcommands are not known to this build, so keep the help
        # and let a person read it; Trueup still uses the fallback for its own results.
        record["reason"] = "entire graph answered, but Trueup has no parser for its output yet; fallback used"
    else:
        record["reason"] = ("entire graph is not available here: " + (out.splitlines()[0] if out else "no output") +
                            ". agent-help lists `entire plugin` as the user's command, so Trueup did not "
                            "install it.")
    return record


def _defs(tree: ast.AST) -> list[tuple[str, int, int, str]]:
    """(qualname, start, end, kind) for every function and class, nested ones included."""
    out: list[tuple[str, int, int, str]] = []

    def walk(node: ast.AST, prefix: str) -> None:
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                q = f"{prefix}{child.name}"
                kind = "class" if isinstance(child, ast.ClassDef) else "function"
                out.append((q, child.lineno, child.end_lineno or child.lineno, kind))
                walk(child, q + ".")
            else:
                walk(child, prefix)

    walk(tree, "")
    return out


def enclosing(defs: list[tuple[str, int, int, str]], line: int) -> str | None:
    """The innermost function or class around a line."""
    best = None
    for q, a, b, _ in defs:
        if a <= line <= b and (best is None or a >= best[1]):
            best = (q, a)
    return best[0] if best else None


def rg_lines(pattern: str, paths: list[Path], run: Runner = run_cmd) -> list[tuple[Path, int, str]]:
    """ripgrep matches in Python files outside tests: (file, line, text)."""
    rg = shutil.which("rg")
    hits: list[tuple[Path, int, str]] = []
    if rg:
        p = run([rg, "-n", "--no-heading", "--type", "py", "-g", "!tests/**", "-e", pattern,
                 *map(str, paths)], None, 120)
        for ln in p.stdout.splitlines():
            f, n, text = ln.split(":", 2)
            hits.append((Path(f), int(n), text.strip()))
        return hits
    import re  # no ripgrep: same search in Python

    rx = re.compile(pattern)
    for base in paths:
        for f in sorted(base.rglob("*.py")):
            if "tests" in f.relative_to(base).parts:
                continue
            for i, text in enumerate(f.read_text(errors="replace").splitlines(), 1):
                if rx.search(text):
                    hits.append((f, i, text.strip()))
    return hits


def locate_symbols(clone: Path, target: Target, run: Runner = run_cmd) -> dict[str, Any]:
    """Definitions of the seeds, their callers, and the reference symbols' uses, via ripgrep + ast."""
    paths = [clone / p.path for p in target.packages]
    trees: dict[Path, list[tuple[str, int, int, str]]] = {}

    def defs_of(f: Path) -> list[tuple[str, int, int, str]]:
        if f not in trees:
            try:
                trees[f] = _defs(ast.parse(f.read_text(errors="replace")))
            except SyntaxError:
                trees[f] = []
        return trees[f]

    rel = lambda f: str(f.resolve().relative_to(clone.resolve()))  # noqa: E731
    definitions, callers = [], []
    for seed in target.seeds:
        for f, n, text in rg_lines(rf"^\s*(async\s+)?(def|class)\s+{seed}\b", paths, run):
            q = enclosing(defs_of(f), n)
            definitions.append({"symbol": seed, "file": rel(f), "line": n, "qualname": q,
                                "end": next((b for qq, a, b, _ in defs_of(f) if qq == q), n)})
        for f, n, text in rg_lines(rf"\b{seed}\b", paths, run):
            if text.lstrip().startswith(("def ", "async def ", "class ", "#", "from ", "import ")):
                continue
            callers.append({"symbol": seed, "file": rel(f), "line": n, "in": enclosing(defs_of(f), n),
                            "text": text[:200]})
    reference = []
    for seed in target.reference_seeds:
        repo_paths = [clone / "packages"] if (clone / "packages").exists() else [clone]
        for f, n, text in rg_lines(rf"\b{seed}\b", repo_paths, run)[:40]:
            if "import" in text:
                continue
            reference.append({"symbol": seed, "file": rel(f), "line": n, "in": enclosing(defs_of(f), n),
                              "text": text[:200]})
    return {"definitions": definitions, "callers": callers, "reference": reference}


def source_excerpts(clone: Path, located: dict[str, Any], limit: int = 40_000) -> str:
    """Whole files that define a seed (most relevant first), then a window around reference uses."""
    parts, total, seen = [], 0, set()
    for d in located["definitions"]:
        if d["file"] in seen:
            continue
        seen.add(d["file"])
        text = (clone / d["file"]).read_text(errors="replace")
        if total + len(text) > limit:
            lines = text.splitlines()
            a, b = max(0, d["line"] - 40), min(len(lines), d["end"] + 40)
            text = "\n".join(f"{i + 1}: {ln}" for i, ln in enumerate(lines[a:b], a))
            text = f"(excerpt, lines {a + 1}-{b})\n{text}"
        total += len(text)
        parts.append(f"### {d['file']}\n{text}")
    for r in located["reference"][:6]:
        lines = (clone / r["file"]).read_text(errors="replace").splitlines()
        a, b = max(0, r["line"] - 12), min(len(lines), r["line"] + 12)
        parts.append(f"### reference {r['file']}:{a + 1}-{b}\n" + "\n".join(lines[a:b]))
    return "\n\n".join(parts)


def locate(root: Path, target: Target, out_dir: Path, run: Runner = run_cmd) -> dict[str, Any]:
    clone, commit = ensure_clone(root, target.library, run)
    graph = probe_graph(clone, target.seeds, run)
    located = locate_symbols(clone, target, run)
    result = {"library": target.library, "code_path": target.code_path, "clone": str(clone), "commit": commit,
              "graph": graph, "method": "entire graph" if graph["used"] else "ripgrep + ast (fallback)",
              **located}
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "locate.json").write_text(json.dumps(result, indent=1))
    return result

"""Verify a patch: the package's own tests, the finding's scenarios, and the full scenario library.

Two venvs per library, both built from the clone in .trueup/clones/<lib>:
  .trueup/venvs/<lib>-fixtest  the patched packages installed editable, with their test requirements;
                               runs the packages' own test suites and the new test
  .trueup/venvs/<lib>-fix      the library as the scenarios use it (PACKAGES), its packages from
                               the clone; the "before" sweep runs on the clean clone, then each try
                               reinstalls the packages from the patched clone
The rules here are pure functions over recorded results; the effects are in the run_* helpers.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import tomllib
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Any, Callable

from trueup.core import checker
from trueup.core.compare import compare, leads
from trueup.core.model import Observation
from trueup.fixer.targets import Package, Target
from trueup.runner import RAN, run_scenario, venvs
from trueup.runner.setups import PACKAGES

SECRET = re.compile(r"KEY|TOKEN|SECRET|PASSWORD", re.I)


class VerifyError(RuntimeError):
    pass


def test_env() -> dict[str, str]:
    """The environment for a library's own tests: no keys of any kind, no outer venv."""
    env = {k: v for k, v in os.environ.items() if not SECRET.search(k)}
    env.pop("VIRTUAL_ENV", None)
    env.pop("PYTHONPATH", None)
    env["OTEL_SDK_DISABLED"] = env.get("OTEL_SDK_DISABLED", "false")
    return env


def _uv() -> str:
    return shutil.which("uv") or "uv"


def _run(cmd: list[str], timeout: float = 1800, cwd: Path | None = None) -> str:
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=cwd, env=test_env())
    if p.returncode != 0:
        raise VerifyError(f"{' '.join(cmd[:4])} failed: {(p.stderr or p.stdout).strip()[-800:]}")
    return p.stdout


def test_requirements(clone: Path, pkg: Package) -> list[str]:
    base = clone / pkg.path
    reqs: list[str] = []
    for dep in pkg.test_deps:
        if dep.startswith("group:"):
            groups = tomllib.loads((base / "pyproject.toml").read_text()).get("dependency-groups", {})
            reqs += [g for g in groups.get(dep[6:], []) if isinstance(g, str)]
        elif dep.startswith("file:"):
            for ln in (base / dep[5:]).read_text().splitlines():
                ln = ln.split("#", 1)[0].strip()
                if ln and not ln.startswith("-"):
                    reqs.append(ln)
        else:
            reqs.append(dep)
    return reqs


def ensure_test_venv(root: Path, clone: Path, target: Target) -> Path:
    d = venvs.venv_dir(root, f"{target.library}-fixtest")
    py = d / "bin" / "python"
    stamp = {"packages": [p.path for p in target.packages]}
    if py.exists() and (d / venvs.STAMP).exists() and json.loads((d / venvs.STAMP).read_text()) == stamp:
        return py
    _run([_uv(), "venv", "--quiet", "--allow-existing", "--python", "3.12", str(d)])
    local = sorted({x for p in target.packages for x in p.local_deps} | {p.path for p in target.packages})
    reqs = sorted({r for p in target.packages for r in test_requirements(clone, p)})
    # Local packages of the repo replace any PyPI release a test requirement pulls in.
    _run([_uv(), "pip", "install", "--quiet", "--python", str(py), *reqs,
          *(a for x in local for a in ("-e", str(clone / x)))])
    (d / venvs.STAMP).write_text(json.dumps(stamp))
    return py


def parse_junit(path: Path) -> dict[str, Any]:
    """Counts and the ids of failed/errored tests from a pytest junit xml."""
    root = ET.parse(path).getroot()
    suites = [root] if root.tag == "testsuite" else list(root)
    total = failed = errors = skipped = 0
    bad: list[str] = []
    for s in suites:
        for tc in s.iter("testcase"):
            total += 1
            tid = f"{tc.get('classname', '')}::{tc.get('name', '')}"
            if tc.find("failure") is not None:
                failed += 1
                bad.append(tid)
            elif tc.find("error") is not None:
                errors += 1
                bad.append(tid)
            elif tc.find("skipped") is not None:
                skipped += 1
    return {"total": total, "passed": total - failed - errors - skipped, "failed": failed, "errors": errors,
            "skipped": skipped, "failing": sorted(set(bad))}


def run_pytest(py: Path, clone: Path, pkg: Package, args: list[str], timeout: float = 2400) -> dict[str, Any]:
    """pytest in the package dir. Records the exit code, counts, failing ids and the output tail."""
    cwd = clone / pkg.path
    junit = cwd / ".trueup-junit.xml"
    junit.unlink(missing_ok=True)
    cmd = [str(py), "-m", "pytest", "-q", "-p", "no:cacheprovider", "-p", "no:sugar", f"--junitxml={junit}",
           *args]
    try:
        p = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True, timeout=timeout, env=test_env())
        code, tail = p.returncode, (p.stdout + p.stderr).strip()[-3000:]
    except subprocess.TimeoutExpired:
        code, tail = -1, f"timed out after {timeout:.0f} s"
    res: dict[str, Any] = {"cmd": " ".join(["pytest", *args]), "cwd": pkg.path, "exit": code, "tail": tail}
    if junit.exists():
        res.update(parse_junit(junit))
        junit.unlink()
    return res


def suite_verdict(before: dict[str, Any], after: dict[str, Any], new_test: str | None) -> tuple[bool, str]:
    """The suite passes, or fails only where it failed before the patch (the new test aside)."""
    if "failing" not in after:
        return False, f"the suite did not run after the patch (exit {after['exit']}): {after['tail'][-400:]}"
    skip = (lambda t: new_test is not None and Path(new_test).stem in t)  # noqa: E731
    new = [t for t in after["failing"] if t not in set(before.get("failing", [])) and not skip(t)]
    if new:
        return False, f"{len(new)} test(s) fail after the patch and passed before: {', '.join(new[:10])}"
    if after["total"] < before.get("total", 0):
        return False, f"fewer tests ran after the patch ({after['total']} vs {before['total']})"
    same = len([t for t in after["failing"] if not skip(t)])
    return True, ("suite passes" if not same else f"same {same} failure(s) as before the patch")


def new_test_verdict(before: dict[str, Any], after: dict[str, Any]) -> tuple[bool, str]:
    """The new test must fail on the unpatched code and pass on the patched code."""
    if before.get("total", 0) == 0:
        return False, f"the new test was not collected before the patch (exit {before['exit']}): " \
                      f"{before['tail'][-600:]}"
    if not before["failing"]:
        return False, "the new test passes on the unpatched code, so it does not show the bug"
    if after.get("total", 0) == 0 or after["failing"]:
        return False, f"the new test fails with the patch (exit {after['exit']}): {after['tail'][-1200:]}"
    return True, f"new test: fails before ({len(before['failing'])} failing), passes after ({after['total']} passed)"


# The scenario side ------------------------------------------------------------------

def ensure_fix_venv(root: Path, clone: Path, library: str) -> Path:
    """PACKAGES from PyPI, with the library's packages from the clone (non-editable)."""
    d = venvs.venv_dir(root, f"{library}-fix")
    py = d / "bin" / "python"
    paths: dict[str, str] = venvs.MAIN_SOURCES[library]["paths"]  # type: ignore[assignment]
    if not py.exists():
        _run([_uv(), "venv", "--quiet", "--allow-existing", "--python", "3.12", str(d)])
    pypi = [p for p in PACKAGES[library] if p not in paths]
    _run([_uv(), "pip", "install", "--quiet", "--python", str(py), *pypi, *(str(clone / p) for p in paths.values())])
    return py


def reinstall(py: Path, clone: Path, target: Target) -> None:
    """Put the clone's current (patched) packages into the -fix venv."""
    _run([_uv(), "pip", "install", "--quiet", "--no-deps", "--reinstall", "--python", str(py),
          *(str(clone / p.path) for p in target.packages)])


def sweep_scenarios(py: Path, library: str, scenario_ids: list[str],
                    run: Callable[..., dict[str, Any]] = run_scenario,
                    out: Callable[[str], None] = print) -> dict[str, Any]:
    """Run scenarios in the venv; leads per scenario (as dicts) and NOT RUN reasons."""
    res: dict[str, Any] = {"leads": {}, "not_run": {}}
    for sid in scenario_ids:
        r = run(py, library, sid)
        if r["status"] != RAN:
            res["not_run"][sid] = r["reason"]
            out(f"    {sid:30} NOT RUN {r['reason']}")
            continue
        ls = [m.to_dict() for m in leads(compare(Observation.from_dict(r["observation"])))]
        res["leads"][sid] = ls
        out(f"    {sid:30} {len(ls)} lead(s)")
    return res


def matches_finding(lead: dict[str, Any], finding: dict[str, Any]) -> bool:
    d = finding["details"]
    return lead.get("check") == d["check"] and lead.get("field") == d["field"]


def scenario_verdict(after: dict[str, Any], finding: dict[str, Any]) -> tuple[bool, str]:
    """Every scenario of the finding ran and none still shows the finding's lead."""
    bad, missing = [], []
    for sid in finding["details"]["scenarios"]:
        if sid not in after["leads"]:
            missing.append(sid)
        elif any(matches_finding(m, finding) for m in after["leads"][sid]):
            bad.append(sid)
    if missing:
        return False, f"scenario(s) did not run: {', '.join(missing)}"
    if bad:
        return False, f"still wrong after the patch: {', '.join(bad)}"
    return True, f"all {len(finding['details']['scenarios'])} scenario(s) of the finding now match truth here"


def new_mismatches(before: dict[str, Any], after: dict[str, Any]) -> list[dict[str, Any]]:
    """Leads after the patch whose signature was not there before, per scenario. NOT RUN after counts too."""
    out = []
    for sid, ls in after["leads"].items():
        old = {json.dumps(checker.signature(m)) for m in before["leads"].get(sid, [])}
        out += [{**m, "scenario": sid} for m in ls if json.dumps(checker.signature(m)) not in old]
    out += [{"scenario": sid, "check": "not_run", "field": "-", "truth": "ran before", "trace": reason}
            for sid, reason in after["not_run"].items() if sid not in before["not_run"]]
    return out


def before_after(finding: dict[str, Any], before: dict[str, Any], after: dict[str, Any]) -> list[dict[str, Any]]:
    rows = []
    for sid in finding["details"]["scenarios"]:
        b = next((m for m in before["leads"].get(sid, []) if matches_finding(m, finding)), None)
        a = next((m for m in after["leads"].get(sid, []) if matches_finding(m, finding)), None)
        truth = (b or a or {}).get("truth", "?")
        rows.append({"scenario": sid, "field": finding["details"]["field"], "truth": truth,
